import { OPEN_API_PY_CLIENT_DEPENDENCIES } from '../../open-api/py-client/generator.js';
import { DEPENDENCIES as PY_AGENT_DEPENDENCIES } from '../../py/agent/generator.js';
import { DEPENDENCIES as PY_DYNAMODB_DEPENDENCIES } from '../../py/dynamodb/generator.js';
import { declaredNames } from '../declared-dependencies.js';
import { PY_VERSIONS, withPyVersions } from '../versions.js';

/**
 * The packages a client generated by `open-api#py-client` imports, at the
 * versions the generator vends — so a worker runs the code under test against
 * exactly what a consumer gets.
 */
export const PY_CLIENT_VERIFIER_DEPENDENCIES: string[] = withPyVersions(
  OPEN_API_PY_CLIENT_DEPENDENCIES,
  declaredNames(OPEN_API_PY_CLIENT_DEPENDENCIES.py),
);

/** The type checker every Python worker installs alongside its dependencies. */
export const PY_VERIFIER_TYPE_CHECKER = `ty${PY_VERSIONS.ty}`;

/**
 * The packages a project generated by `py#dynamodb` imports, at the versions
 * the generator vends. The worker itself imports the py-client packages, so
 * they are included too.
 */
export const PY_DYNAMODB_VERIFIER_DEPENDENCIES: string[] = [
  ...withPyVersions(
    PY_DYNAMODB_DEPENDENCIES,
    declaredNames(PY_DYNAMODB_DEPENDENCIES.py),
  ),
  ...PY_CLIENT_VERIFIER_DEPENDENCIES,
];

/**
 * The packages a Strands or LangChain agent generated by `py#agent` imports
 * from agent.py and guardrail.py, at the versions the generator vends, plus
 * the ruff the vended lint and format targets run.
 */
export const PY_AGENT_GUARDRAIL_VERIFIER_DEPENDENCIES: string[] = [
  ...withPyVersions(PY_AGENT_DEPENDENCIES, [
    'aws-lambda-powertools',
    'boto3',
    'strands-agents',
    'strands-agents-tools',
    'langchain',
    'langchain-aws',
    'langgraph',
    'langgraph-checkpoint-sqlite',
    'aiosqlite',
  ]),
  `ruff${PY_VERSIONS.ruff}`,
];
